// ---------------------------------------------------------------------------
// Icons contributed by lane-b (merged union; no name overlaps with the above).
// ---------------------------------------------------------------------------

// Lucide icon paths.
//
// beUI imports its icons from `lucide-react`. Each icon there is the same
// `<svg>` shell — `viewBox="0 0 24 24"`, `fill="none"`, `stroke="currentColor"`,
// 2px round caps — with the glyph's own path data. This module carries the
// path data verbatim for the icons the ported components use, so a port draws
// the identical glyph instead of a hand-rolled approximation.
//
// Every icon takes the same `class` escape hatch the source's `className`
// gives it; the Lucide `lucide lucide-*` classes are kept so that a selector
// written against the source keeps matching.

/// The common Lucide `<svg>` shell. `name` is the hyphenated icon name, used to
/// build the same `lucide lucide-<name>` class list the React package emits.
#[component]
fn Lucide(name: &'static str, class: Option<String>, children: Element) -> Element {
    let class = match class {
        Some(extra) => format!("lucide lucide-{name} {extra}"),
        None => format!("lucide lucide-{name}"),
    };
    rsx! {
        svg {
            xmlns: "http://www.w3.org/2000/svg",
            width: "24",
            height: "24",
            "viewBox": "0 0 24 24",
            fill: "none",
            stroke: "currentColor",
            "stroke-width": "2",
            "stroke-linecap": "round",
            "stroke-linejoin": "round",
            class,
            {children}
        }
    }
}

